function shuffleStable(items,key){
 let seed=2166136261;for(const ch of key){seed=Math.imul(seed^ch.charCodeAt(0),16777619)>>>0;}
 const result=[...items];for(let i=result.length-1;i>0;i--){seed=(Math.imul(seed,1664525)+1013904223)>>>0;const j=seed%(i+1);[result[i],result[j]]=[result[j],result[i]];}
 return result;
}
